	a := append(append([]string{}, testdata_l...), "builtins", "trimprefix")
	for i := len(a); 0 <= i; i-- {
		k := sf(`[testdata] %[1]s false`, a[i:])
		v := sf(`false [] %[1]s [] %[2]d %[2]d ILLEGAL`, a[i:], len(a)-i)
		m[k] = v ; if false { fmt.Printf(`"%v":"%v"`+"\n", k, v) }
	}
	return m
