func check__string_com(ctx Context, _c *compound, _v Value) {
	var (
		k = sf("%v", _c)
		t = sf("%v", _v)
		v = checkpoints__string_com[k]
	)
	if v == nil {
		if k == t { return }
		debug(pc(ctx,_c),
			_f("`%v`:`%v`,", _c, _v),
			_f("%v", ts(_c, ctx)),
			_f("%v", ts(_v, ctx)),
			callstack{num:5}, trace{})
	} else {
		switch w := v.(type) {
		case []string: for _, v := range w { if t == v { return } }
		case   string:                       if t == w { return }
		}
		debug(pc(ctx,_c),
			_f(`%v → %v != %v ; %v`, _c, t, v, _c.elems),
			_f("%v", ts(_c, ctx)),
			_f("%v", ts(_v, ctx)),
			callstack{num:5}, trace{})
	}
	return
}

