func check_cache(ctx Context, _k any, c0 string, c *valcache, r []*valcache) {
	var (
		k = unloc(_k.(Value))
		ks = sf("%v %s", c0, k)
		vs = sf("%v %v", c, r)
		rs, y = checkpoints_cache[ks]
	)
	if !y {
		if p := _project(ctx); p != nil { switch spec := p.spec.String(); {
		case strings.HasSuffix(spec, ".smart/modules/lib/unwind"): return
		case strings.HasSuffix(spec, ".smart/modules/lib/c++abi"): return
		case strings.HasSuffix(spec, ".smart/modules/lib/c++inc"): return
		case strings.HasSuffix(spec, ".smart/modules/lib/c++"): return
		case strings.HasSuffix(spec, ".smart/modules/variant/.target"):
			if d := p.resolveDef(ctx, intern("c++.std")); d != nil && strings.Contains(d.value.String(), k.String()) {
				if false { erro(ctx, "%v", d) }
				return
			}
		}}

		if true { prompt(ctx, "	`%v`:`%v`,//cache\n", ks, vs) } else
		{ debug(pc(ctx,_k),
			_f("%s: `%s`:`%s`,", typeof(k), ks, vs),
			callstack{num:32,/* stop:"smart.hit", */}, trace{}) }
	} else if vs != rs {
		if false { prompt(ctx, "	`%v`:`%v`,\n", ks, vs) } else
		{ debug(pc(ctx,_k),
			_f("%s: %v", typeof(k), ks),
			_f("got: %v", vs),
			_f("!= : %v", rs),
			callstack{num:32,/* stop:"smart.hit" */}, trace{}) }
	}
}

