func (prog *program) execute_check_shell_for_stdout(ctx Context, result *Value) {
	var ent = _entry(ctx)

	if *result == nil {
		debug(ctx, "%v: nil result", ts(ent,ctx))
	}

    var args = try[[]Value](ctx, get_args{})
	var o = try[origin](ctx, get_origin{})

    switch __string(ctx, ent.destiny()) {
    case ".test.0":
		if len(_execution(ctx).interpreted) == 0 {
            debug(ctx, "%v: not interpreted", ent)
		}
        if len(args) != 2 {
            debug(ctx, "%v: %d %v", ent, len(args), ts(args,ctx))
        }
        if len(prog.params) != 2 {
            debug(ctx, "%v: %d %v", ent, len(prog.params), ts(prog.params,ctx))
        }
		if v := auto_get(ctx, intern("@")); ts(v,ctx) != "{=qualword {5:1} {5:2:word test} {5:7:decimal 0}}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern("<")); ts(v,ctx) != "{}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern(">")); ts(v,ctx) != "{}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern("-")); ts(v,ctx) != ts(*result,ctx) {
			debug(ctx, "%s != %s", ts(v,ctx), ts(*result,ctx))
		}
		if v := auto_get(ctx, intern("-")); v != *result {
			debug(ctx, "%s != %s", ts(v,ctx), ts(*result,ctx))
		}

		switch o {
		case defExpand0:
			if s, t := ts(*result,ctx), sf("{=delegate {=builtin debug} {=list %s %s}}", ts(args[1],ctx), ts(args[0],ctx)); s != t {
				debug(ctx, "%v (%s %s)", ts(*result,ctx), ts(args[1],ctx), ts(args[0],ctx))
			}
		case defExpand1:
			if s, t := ts(*result,ctx), "{6:2:null}"; s != t {
				debug(ctx, "%v (%s %s)", ts(*result,ctx), ts(args[1],ctx), ts(args[0],ctx))
			}
		}
    case ".test1":
		if v := auto_get(ctx, intern("@")); ts(v,ctx) != "{=qualword {19:1} {19:2:word test1}}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern("<")); ts(v,ctx) != "{}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern(">")); ts(v,ctx) != "{}" {
			debug(ctx, "%v", ts(v,ctx))
		}
    case ".test2":
		if v := auto_get(ctx, intern("@")); ts(v,ctx) != "{=qualword {23:1} {23:2:word test2}}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern("<")); ts(v,ctx) != "{}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern(">")); ts(v,ctx) != "{}" {
			debug(ctx, "%v", ts(v,ctx))
		}
    case ".test":
        if len(args) != 2 { // NOTE: always use two args in this test case
            debug(ctx, "%v: %d %v", ent, len(args), ts(args))
        }
		if v := auto_get(ctx, intern("@")); ts(v,ctx) != "{=qualword {11:1} {11:2:word test}}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern("<")); ts(v,ctx) != "{}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern(">")); ts(v,ctx) != "{}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern("-")); ts(v,ctx) != ts(*result,ctx) {
			debug(ctx, "%s != %s", ts(v,ctx), ts(*result,ctx))
		}
		if v := auto_get(ctx, intern("-")); v != *result {
			debug(ctx, "%s != %s", ts(v,ctx), ts(*result,ctx))
		}

		switch ts(args,ctx) {
		case "{=[Value] {=list {=delegate {=auto 1}}} {=list {=delegate {=auto 2}}}}":
			switch o {
			case defExpand0, defExpand1:
				if ts(*result,ctx) != "{=delegate {=builtin debug} {=list {=delegate {=auto 2}} {=delegate {=auto 1}}}}" {
					debug(ctx, ".test: %v, %s", ts(*result,ctx), ts(args,ctx))
				}
			}
		default:
			switch o {
			case defExpand0:
				t := sf("{=delegate {=builtin debug} {=list %s %s}}", ts(args[1],ctx), ts(args[0],ctx))
				if ts(*result,ctx) != t {
					debug(ctx, ".test: %v != %s, %s", ts(*result,ctx), t, ts(args,ctx))
				}
			case defExpand1:
				if ts(*result,ctx) != "{12:2:null}" {
					debug(ctx, ".test: %v %v", ts(*result,ctx), ts(args,ctx))
				}
			}
		}
	}

	switch o {
	case defExpand0, defExpand1, 0:
	default:
		debug(ctx, "untested: %v: %v %s %s", ent.destiny(), o, ts(args,ctx), ts(*result,ctx))
	}
}


func (cc *configurecontext) execute_check(ctx *execution, e entry, p *project, s *string, _d **def) {
	switch p.name {
	case intern("testdefaultconfigure"):
		if d := *_d; d == nil {
			erro(ctx, "%v", e)
		} else {
			switch d.name {
			case intern("FOO"):
				if d.value.String() != "{=self testdefaultconfigure}" {
					erro(ctx, "%v", d.value)
				}
			}
		}
	}
}

var rx_sha256 = regexp.MustCompile(`[0-9a-f]{40}`) // 24be3fc4dbc8099b28a7afa44fd7711d62a4580b
var rx_checking_for = regexp.MustCompile(`^checking for (.+?) …$`)
var rx_checking_res = regexp.MustCompile(`^… (.*?)\n$`)
func (l ul) configure_val_check(ctx *execution, name Symbol, op Value, vals []Value, a, b *diagpoint) {
	var c Context = ctx
	var ss, _ = do(ctx, l_filename("?")).([]string)
	for _, s := range ss { c = pc(c, s) }

	if sm := rx_checking_for.FindStringSubmatch(a.message); sm != nil {
		m := rx_checking_res.FindStringSubmatch(b.message)
		if m == nil {
			erro(ctx, "%s: %v %v, %v, %v", sm[1], op, vals, l.project.elems[name], ctx.recipes)
		}

		var chk map[string]string

		chk = configure_chk_darwin(ctx, sm, m)

		if x, y := chk[sm[1]]; y {
			switch {
			case x == "?!":
				if false {
					debug(c, "%s: %s: %s", auto_get(ctx, intern("@")), sm[1], m[1])
				}
			case x == "?SHA256!":
				if !rx_sha256.MatchString(m[1]) {
					erro(c, "%s: %s: %s", auto_get(ctx, intern("@")), sm[1], m[1])
				}
			case x == "?OUTBIN!":
				if d := l.project.resolveDef(ctx, intern("outbin")); d == nil {
					erro(c, "%s: %s: %s", auto_get(ctx, intern("@")), sm[1], m[1])
				} else if s := __string(ctx, d); s != m[1] {
					erro(c, "%s: %s: %s != %s", auto_get(ctx, intern("@")), sm[1], m[1], s)
				}
			case x != m[1]:
				erro(c, "%s: %s: %s != %s", auto_get(ctx, intern("@")), sm[1], m[1], x)
			}
		} else {
			erro(c, "unknown configure check: %s %s", sm[1], m[1])
		}
	} else {
		erro(c, "%v → %v", ts(op,ctx), ts(vals,ctx))
	}
}

